    16  UA_UInt16 addNamespace(UA_Server *server, const UA_String name) {
    17      /* Check if the namespace already exists in the server's namespace array */
    18      for(UA_UInt16 i = 0; i < server->namespacesSize; ++i) {
    19          if(UA_String_equal(&name, &server->namespaces[i]))
    20              return i;
    21      }
    22
    23      /* Make the array bigger */
    24      UA_String *newNS = (UA_String*)UA_realloc(server->namespaces,
    25                                                sizeof(UA_String) * (server->namespacesSize + 1));
    26      if(!newNS)
    27          return 0;
    28      server->namespaces = newNS;
    29
    30      /* Copy the namespace string */
    31      UA_StatusCode retval = UA_String_copy(&name, &server->namespaces[server->namespacesSize]);
    32      if(retval != UA_STATUSCODE_GOOD)
    33          return 0;
    34
    35      /* Announce the change (otherwise, the array appears unchanged) */
    36      ++server->namespacesSize;
    37      return (UA_UInt16)(server->namespacesSize - 1);
    38  }
