    48  UA_StatusCode
    49  UA_Server_forEachChildNodeCall(UA_Server *server, UA_NodeId parentNodeId,
    50                                 UA_NodeIteratorCallback callback, void *handle) {
    51      const UA_Node *parent =
    52          server->config.nodestore.getNode(server->config.nodestore.context,
    53                                           &parentNodeId);
    54      if(!parent)
    55          return UA_STATUSCODE_BADNODEIDINVALID;
    56
    57      /* TODO: We need to do an ugly copy of the references array since users may
    58       * delete references from within the callback. In single-threaded mode this
    59       * changes the same node we point at here. In multi-threaded mode, this
    60       * creates a new copy as nodes are truly immutable. */
    61      UA_ReferenceNode *refs = NULL;
    62      size_t refssize = parent->referencesSize;
    63      UA_StatusCode retval = UA_Array_copy(parent->references, parent->referencesSize,
    64          (void**)&refs, &UA_TYPES[UA_TYPES_REFERENCENODE]);
    65      if(retval != UA_STATUSCODE_GOOD) {
    66          server->config.nodestore.releaseNode(server->config.nodestore.context, parent);
    67          return retval;
    68      }
    69
    70      for(size_t i = parent->referencesSize; i > 0; --i) {
    71          UA_ReferenceNode *ref = &refs[i - 1];
    72          retval |= callback(ref->targetId.nodeId, ref->isInverse,
    73                             ref->referenceTypeId, handle);
    74      }
    75
    76      server->config.nodestore.releaseNode(server->config.nodestore.context, parent);
    77      UA_Array_delete(refs, refssize, &UA_TYPES[UA_TYPES_REFERENCENODE]);
    78      return retval;
    79  }
