    85  /* The server needs to be stopped before it can be deleted */
    86  void UA_Server_delete(UA_Server *server) {
    87      /* Delete all internal data */
    88      UA_SecureChannelManager_deleteMembers(&server->secureChannelManager);
    89      UA_SessionManager_deleteMembers(&server->sessionManager);
    90      UA_Array_delete(server->namespaces, server->namespacesSize, &UA_TYPES[UA_TYPES_STRING]);
    91
    92  #ifdef UA_ENABLE_DISCOVERY
    93      registeredServer_list_entry *rs, *rs_tmp;
    94      LIST_FOREACH_SAFE(rs, &server->registeredServers, pointers, rs_tmp) {
    95          LIST_REMOVE(rs, pointers);
    96          UA_RegisteredServer_deleteMembers(&rs->registeredServer);
    97          UA_free(rs);
    98      }
    99      periodicServerRegisterCallback_entry *ps, *ps_tmp;
   100      LIST_FOREACH_SAFE(ps, &server->periodicServerRegisterCallbacks, pointers, ps_tmp) {
   101          LIST_REMOVE(ps, pointers);
   102          UA_free(ps->callback);
   103          UA_free(ps);
   104      }
   105
   106  # ifdef UA_ENABLE_DISCOVERY_MULTICAST
   107      if(server->config.applicationDescription.applicationType == UA_APPLICATIONTYPE_DISCOVERYSERVER)
   108          destroyMulticastDiscoveryServer(server);
   109
   110      serverOnNetwork_list_entry *son, *son_tmp;
   111      LIST_FOREACH_SAFE(son, &server->serverOnNetwork, pointers, son_tmp) {
   112          LIST_REMOVE(son, pointers);
   113          UA_ServerOnNetwork_deleteMembers(&son->serverOnNetwork);
   114          if(son->pathTmp)
   115              UA_free(son->pathTmp);
   116          UA_free(son);
   117      }
   118
   119      for(size_t i = 0; i < SERVER_ON_NETWORK_HASH_PRIME; i++) {
   120          serverOnNetwork_hash_entry* currHash = server->serverOnNetworkHash[i];
   121          while(currHash) {
   122              serverOnNetwork_hash_entry* nextHash = currHash->next;
   123              UA_free(currHash);
   124              currHash = nextHash;
   125          }
   126      }
   127  # endif
   128
   129  #endif
   130
   131  #ifdef UA_ENABLE_MULTITHREADING
   132      pthread_cond_destroy(&server->dispatchQueue_condition);
   133      pthread_mutex_destroy(&server->dispatchQueue_mutex);
   134  #endif
   135
   136      /* Delete the timed work */
   137      UA_Timer_deleteMembers(&server->timer);
   138
   139      /* Delete the server itself */
   140      UA_free(server);
   141  }
