   144  static void
   145  UA_Server_cleanup(UA_Server *server, void *_) {
   146      UA_DateTime nowMonotonic = UA_DateTime_nowMonotonic();
   147      UA_SessionManager_cleanupTimedOut(&server->sessionManager, nowMonotonic);
